// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Interface describing SGD trainer parameters.
*/
interface Params {
	/**
	* Parameters specific to the regularization function being used.
	*
	* ## Notes
	*
	* -   Must be an array having length `2`, with any unused elements set to zero. The expected array contents depend on the penalty:
	*
	*     -   **l1**: `[ lambda, 0.0 ]`
	*     -   **l2**: `[ lambda, 0.0 ]`
	*     -   **elasticnet**: `[ lambda, l1Ratio ]`
	*     -   **none**: `[ 0.0, 0.0 ]` (unused)
	*
	*     where:
	*
	*     -   **lambda**: regularization parameter which determines the amount of shrinkage inflicted on the model coefficients.
	*     -   **l1Ratio**: mixing parameter on the interval `[0,1]` which determines the relative contribution of the L1 and L2 penalties.
	*/
	penaltyParams?: Float64Array;

	/**
	* Parameters specific to the learning rate scheduler being used.
	*
	* ## Notes
	*
	* -   Must be an array having length `2`, with any unused elements set to zero. The expected array contents depend on the learning rate scheduler:
	*
	*     -   **basic**: `[ 0.0, 0.0 ]` (unused)
	*     -   **constant**: `[ eta0, 0.0 ]`
	*     -   **invscaling**: `[ eta0, powerT ]`
	*     -   **pegasos**: `[ lambda, 0.0 ]`
	*
	*     where:
	*
	*     -   **eta0**: initial learning rate.
	*     -   **powerT**: exponent controlling how quickly the learning rate decreases.
	*     -   **lambda**: regularization parameter.
	*/
	learningRateParams?: Float64Array;

	/**
	* Parameters specific to the loss function being used.
	*
	* ## Notes
	*
	* -   Must be an array having length `1`. The expected array contents depend on the loss function:
	*
	*     -   **epsilon-insensitive**: `[ epsilon ]`
	*     -   **squared-epsilon-insensitive**: `[ epsilon ]`
	*     -   **huber**: `[ threshold ]`
	*     -   all other loss functions: `[ 0.0 ]` (unused)
	*
	*     where:
	*
	*     -   **epsilon**: insensitivity parameter (i.e., errors whose absolute value is less than `epsilon` incur no penalty).
	*     -   **threshold**: error magnitude at which the loss transitions from squared-error loss to linear loss.
	*/
	lossFunctionParams?: Float64Array;

	/**
	* Initial intercept value.
	*
	* ## Notes
	*
	* -   Only applicable when `fitIntercept` is `true`.
	*/
	intercept?: number;

	/**
	* Maximum number of iterations to run.
	*/
	maxIter?: number;

	/**
	* Regularization function.
	*/
	penalty?: number;

	/**
	* Learning rate scheduler.
	*/
	learningRate?: number;

	/**
	* Loss function.
	*/
	lossFunction?: number;

	/**
	* Boolean indicating whether to include intercept.
	*
	* ## Notes
	*
	* -   If `true`, an element equal to one is implicitly added to each provided feature vector. If `false`, the model assumes that feature vectors are already centered.
	*/
	fitIntercept?: boolean;
}

/**
* Interface describing `dsgdTrainer`.
*/
interface Routine {
	/**
	* Trains a linear model via stochastic gradient descent.
	*
	* @param order - storage layout
	* @param M - number of samples
	* @param N - number of features
	* @param X - input matrix
	* @param LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
	* @param y - target array
	* @param strideY - stride length for `y`
	* @param w - weight array
	* @param strideW - stride length for `w`
	* @param workspace - workspace array of size `N` for tracking total L1 shrinkage applied to each feature
	* @param strideWS - stride length for `workspace`
	* @param params - parameters object
	* @returns `w`
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
	* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
	*
	* var M = 50;
	* var N = 5;
	* var lambda = 2.5;
	* var eta0 = 0.01;
	*
	* var params = new Params({
	*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
	*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
	*    'intercept': 0.0,
	*    'maxIter': 500,
	*    'penalty': 'l2',
	*    'learningRate': 'constant',
	*    'lossFunction': 'hinge',
	*    'fitIntercept': true
	* });
	*
	* var y = discreteUniform( M, 0.0, 30.0 );
	* var x = discreteUniform( M*N, -5.0, 5.0 );
	* var w = discreteUniform( N, -0.05, 0.05 );
	* var workspace = new Float64Array( N );
	*
	* var out = dsgdTrainer( 'row-major', M, N, x, N, y, 1, w, 1, workspace, 1, params );
	* returns <Float64Array>
	*/
	( order: Layout, M: number, N: number, X: Float64Array, LDX: number, y: Float64Array, strideY: number, w: Float64Array, strideW: number, ws: Float64Array, strideWS: number, params: Params ): Float64Array;

	/**
	* Trains a linear model via stochastic gradient descent using alternative indexing semantics.
	*
	* @param M - number of samples
	* @param N - number of features
	* @param X - input matrix
	* @param strideX1 - stride of the first dimension of `X`
	* @param strideX2 - stride of the second dimension of `X`
	* @param offsetX - starting index for `X`
	* @param y - target array
	* @param strideY - stride length for `y`
	* @param offsetY - starting index for `y`
	* @param w - weight array
	* @param strideW - stride length for `w`
	* @param offsetW - starting index for `w`
	* @param workspace - workspace array
	* @param strideWS - stride length for `workspace`
	* @param offsetWS - starting index for `workspace`
	* @param {Params} params - parameters object
	* @returns `y`
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
	* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
	*
	* var M = 50;
	* var N = 5;
	* var lambda = 2.5;
	* var eta0 = 0.01;
	*
	* var params = new Params({
	*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
	*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
	*    'intercept': 0.0,
	*    'maxIter': 500,
	*    'penalty': 'l2',
	*    'learningRate': 'constant',
	*    'lossFunction': 'hinge',
	*    'fitIntercept': true
	* });
	*
	* var y = discreteUniform( M, 0.0, 30.0 );
	* var X = discreteUniform( M*N, -5.0, 5.0 );
	* var w = discreteUniform( N, -0.05, 0.05 );
	* var workspace = new Float64Array( N );
	*
	* var out = dsgdTrainer.ndarray( M, N, X, N, 1, 0, y, 1, 0, w, 1, 0, workspace, 1, 0, params );
	* returns <Float64Array>
	*/
	ndarray( M: number, N: number, X: Float64Array, strideX1: number, strideX2: number, offsetX: number, y: Float64Array, strideY: number, offset: number, w: Float64Array, strideW: number, offsetW: number, ws: Float64Array, strideWS: number, offsetWS: number, params: Params ): Float64Array;
}

/**
* Trains a linear model via stochastic gradient descent.
*
* @param order - storage layout
* @param M - number of samples
* @param N - number of features
* @param X - input matrix
* @param LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
* @param y - target array
* @param strideY - stride length for `y`
* @param w - weight array
* @param strideW - stride length for `w`
* @param workspace - workspace array of size `N` for tracking total L1 shrinkage applied to each feature
* @param strideWS - stride length for `workspace`
* @param params - parameters object
* @returns `w`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
*
* var M = 50;
* var N = 5;
* var lambda = 2.5;
* var eta0 = 0.01;
*
* var params = new Params({
*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
*    'intercept': 0.0,
*    'maxIter': 500,
*    'penalty': 'l2',
*    'learningRate': 'constant',
*    'lossFunction': 'hinge',
*    'fitIntercept': true
* });
*
* var y = discreteUniform( M, 0.0, 30.0 );
* var x = discreteUniform( M*N, -5.0, 5.0 );
* var w = discreteUniform( N, -0.05, 0.05 );
* var workspace = new Float64Array( N );
*
* var out = dsgdTrainer( 'row-major', M, N, x, N, y, 1, w, 1, workspace, 1, params );
* returns <Float64Array>
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Params = require( '@stdlib/ml/base/sgd/params/float64' );
* var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
*
* var M = 50;
* var N = 5;
* var lambda = 2.5;
* var eta0 = 0.01;
*
* var params = new Params({
*    'penaltyParams': new Float64Array( [ lambda, 0.0 ] ),
*    'learningRateParams': new Float64Array( [ eta0, 0.0 ] ),
*    'intercept': 0.0,
*    'maxIter': 500,
*    'penalty': 'l2',
*    'learningRate': 'constant',
*    'lossFunction': 'hinge',
*    'fitIntercept': true
* });
*
* var y = discreteUniform( M, 0.0, 30.0 );
* var X = discreteUniform( M*N, -5.0, 5.0 );
* var w = discreteUniform( N, -0.05, 0.05 );
* var workspace = new Float64Array( N );
*
* var out = dsgdTrainer.ndarray( M, N, X, N, 1, 0, y, 1, 0, w, 1, 0, workspace, 1, 0, params );
* returns <Float64Array>
*/
declare var dsgdTrainer: Routine;


// EXPORTS //

export = dsgdTrainer;
